def scan():
    return list(map(int, sys.stdin.readline().strip().split()))


def prime(n):
    a = [0]*(n+1)
    for i in range(2, n+1):
        if a[i]:
            continue
        for j in range(2*i, n+1, i):
            a[j] = 1
    return a


