    n=len(s)
    if(n==1):
        return s[0]
    elif(n==2):
        return (s[1] + (s[1]-s[0]))
    else:
        d=s[1]-s[0]
        for i in range(2,n):
            if((s[i]-s[i-1])==d):
                if(i==n-1):
                    return (s[i] + d)
                continue
            else:
                return s[i]


